function f(n){const e=new Date(n),c=new Date().getTime()-e.getTime(),a=Math.floor(c/1e3),o=Math.floor(a/60),r=Math.floor(o/60),i=Math.floor(r/24);return a<60?"just now":o<60?`${o}m ago`:r<24?`${r}h ago`:i<7?`${i}d ago`:e.toLocaleDateString("en-US",{month:"short",day:"numeric"})}function u(n,e="short"){const t=new Date(n);if(isNaN(t.getTime()))return"";switch(e){case"long":return t.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"});case"datetime":return t.toLocaleDateString("en-US",{year:"numeric",month:"short",day:"numeric",hour:"numeric",minute:"2-digit",hour12:!1});default:return t.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})}}export{u as f,f as t};
